import { spawnSync } from 'node:child_process';
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
const root='C:/Users/ash/Desktop/PROJECTS/lunR-pr77-validation-base';
const output='C:/Users/ash/AppData/Local/Temp/lunr-pr77-mergeable/ci-repair';
const env=Object.fromEntries(Object.entries(process.env).filter(([k])=>/^(PATH|SYSTEMROOT|WINDIR|COMSPEC|PATHEXT|TEMP|TMP|SYSTEMDRIVE|NUMBER_OF_PROCESSORS|PROCESSOR_ARCHITECTURE|PROGRAMFILES|PROGRAMFILES\(X86\))$/i.test(k)));
const home=join(output,'full-home');mkdirSync(home,{recursive:true});Object.assign(env,{HOME:home,USERPROFILE:home,APPDATA:join(home,'appdata'),LOCALAPPDATA:join(home,'localappdata'),PI_CODING_AGENT_DIR:join(home,'agent'),PI_OFFLINE:'1',PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD:'1',AWS_EC2_METADATA_DISABLED:'true'});
const mode=process.argv[2];
function run(label,command,args,cwd=root,timeout=360000){const r=spawnSync(command,args,{cwd,env,encoding:'utf8',timeout,shell:command==='npm.cmd',maxBuffer:64*1024*1024});writeFileSync(join(output,`${label}.log`),(r.stdout??'')+'\n'+(r.stderr??'')+'\n'+(r.error?.message??''));console.log(label,r.status,r.error?.message??'');return r.status===0;}
const npm=process.platform==='win32'?'npm.cmd':'npm';
if(mode==='build'){
 for(const pkg of ['tui','ai','agent','coding-agent','orchestrator'])if(!run(`build-${pkg}`,process.execPath,['node_modules/@typescript/native-preview/bin/tsgo.js','-p',`packages/${pkg}/tsconfig.build.json`]))process.exit(1);
 if(!run('bundle',npm,['--prefix','packages/coding-agent','run','build']))process.exit(1);
 if(!run('first-request',process.execPath,['scripts/check-interactive-first-paint.mjs']))process.exit(1);
}else if(mode==='ai'||mode==='coding-agent'){
 const cwd=join(root,'packages',mode);const ok=run(`full-${mode}`,process.execPath,['node_modules/vitest/vitest.mjs','--run','--maxWorkers=4','--reporter=json',`--outputFile=${join(output,`full-${mode}.json`)}`],cwd,600000);process.exitCode=ok?0:1;
}else if(mode==='other'){
 for(const pkg of ['tui','agent','orchestrator'])run(`full-${pkg}`,npm,['--prefix',`packages/${pkg}`,'test']);
}else throw Error('mode required');

